<?php require 'config/db.php'; require 'config/auth.php'; require_login();
$type=$_GET['type']??'transactions'; header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename="'.$type.'_'.date('Ymd_His').'.csv"'); $out=fopen('php://output','w');
if($type==='monthly'){$month=$_GET['month']??date('Y-m'); fputcsv($out,['Date/Time','Serial No','Item Description','Action','Quantity','PIC','Week','Location','Remarks']); $s=$pdo->prepare("SELECT t.*,i.item_description,i.serial_number,i.location FROM transactions t JOIN items i ON i.id=t.item_id WHERE t.month_key=? ORDER BY t.transacted_at DESC"); $s->execute([$month]);}
else {fputcsv($out,['Date/Time','Serial No','Item Description','Action','Quantity','PIC','Week','Location','Remarks']); $where=[];$p=[]; if(!empty($_GET['action_type'])){$where[]='t.action_type LIKE ?';$p[]='%'.$_GET['action_type'].'%';} if(!empty($_GET['pic'])){$where[]='t.pic LIKE ?';$p[]='%'.$_GET['pic'].'%';} if(!empty($_GET['item'])){$where[]='i.item_description LIKE ?';$p[]='%'.$_GET['item'].'%';} if(!empty($_GET['date_from'])){$where[]='DATE(t.transacted_at)>=?';$p[]=$_GET['date_from'];} if(!empty($_GET['date_to'])){$where[]='DATE(t.transacted_at)<=?';$p[]=$_GET['date_to'];} $sql='SELECT t.*,i.item_description,i.serial_number,i.location FROM transactions t JOIN items i ON i.id=t.item_id '.($where?'WHERE '.implode(' AND ',$where):'').' ORDER BY t.transacted_at DESC'; $s=$pdo->prepare($sql); $s->execute($p);}
while($r=$s->fetch()){fputcsv($out,[$r['transacted_at'],$r['serial_number'],$r['item_description'],$r['action_type'],$r['quantity'],$r['pic'],'Week '.$r['week_no'],$r['location'],$r['remarks']]);}
